//! Images embedded in the binary, generated by `packaging/make_icons.py`.

/// The bare QuitCode logo, 128 px, shown in the window header.
pub const LOGO_PNG: &[u8] = include_bytes!("../../../packaging/icons/logo.png");
/// The app icon (logo on a rounded tile), used for the window and taskbar.
pub const APP_ICON_PNG: &[u8] = include_bytes!("../../../packaging/icons/256x256.png");

/// Decodes an embedded RGBA PNG into (pixels, width, height).
pub fn decode(png_bytes: &[u8]) -> (Vec<u8>, u32, u32) {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(png_bytes));
    decoder.set_transformations(png::Transformations::EXPAND);
    let mut reader = decoder.read_info().expect("embedded PNG is valid");
    let mut buf = vec![0; reader.output_buffer_size().expect("small image")];
    let info = reader.next_frame(&mut buf).expect("embedded PNG is valid");
    assert_eq!(
        info.color_type,
        png::ColorType::Rgba,
        "embedded PNG must be RGBA"
    );
    buf.truncate(info.buffer_size());
    (buf, info.width, info.height)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_images_decode() {
        for png_bytes in [LOGO_PNG, APP_ICON_PNG] {
            let (px, w, h) = decode(png_bytes);
            assert_eq!(px.len(), (w * h * 4) as usize);
            assert_eq!(w, h);
        }
    }
}
